import runpy
written=runpy.run_path(str(root/'tools/written_practice.py'))['PROMPTS']
for e in essays:
 e['examPrompts']=[{'question':q,'model':a} for q,a in written[e['lecture']]]
 for heading,paras in extra[e['lecture']]:e['sections'].append(dict(id='section-'+str(len(e['sections'])+1),heading=heading,paragraphs=paras))
 e['wordCount']=sum(len(p.split()) for s in e['sections'] for p in s['paragraphs']);e['readingMinutes']=math.ceil(e['wordCount']/200)
(root/'essays.json').write_text(json.dumps(essays,ensure_ascii=False,indent=2));(root/'essays.js').write_text('window.LECTURE_ESSAYS = '+json.dumps(essays,ensure_ascii=False,separators=(',',':'))+';\n')
print([(e['lecture'],e['wordCount']) for e in essays])
